<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,defineAsyncComponent,watch} from 'vue'
import {ArrowDown,ArrowUpRight,Heart,MapPin,CalendarDays,Menu,X,UserRound,Music2,Sparkles,Bus,Hotel,Shirt} from 'lucide-vue-next'
import Paw from './components/Paw.vue'
import VirtualDog from './components/DogSprite.vue'
import {installed} from './lib/install'
import AuthModal from './components/AuthModal.vue'
import GuestArea from './components/GuestArea.vue'
import SongForm from './components/SongForm.vue'
import {db,fail,friendly} from './lib/supabase'
import {initializeAuth,user,isAdmin,authReady,profile} from './lib/session'
import {defaults,type Settings} from './lib/types'
import {appBase} from './lib/urls'
const InvitePostcard=defineAsyncComponent(()=>import('./components/InvitePostcard.vue'))
const inviteToken=ref(new URLSearchParams(location.hash.slice(1)).get('invite')||'')
watch(()=>[user.value?.id,authReady.value],()=>{const token=user.value?.user_metadata.wedding_invite_token;if(authReady.value&&!inviteToken.value&&!profile.value&&typeof token==='string'&&/^[a-f0-9]{64}$/.test(token))inviteToken.value=token})
const gameApp=ref(location.hash==='#mascota'||installed.value)
const DogGame=defineAsyncComponent(()=>import('./components/DogGame.vue'))
const AdminPanel=defineAsyncComponent(()=>import('./components/AdminPanel.vue'))
const settings=ref<Settings>(structuredClone(defaults)),settingsLoaded=ref(false),authOpen=ref(false),recovery=ref(false),menuOpen=ref(false),gameOpen=ref(false),admin=ref(location.pathname==='/admin'||location.hash==='#admin'),error=ref(''),now=ref(Date.now())
let clock:ReturnType<typeof setInterval>
const date=computed(()=>settings.value.date?new Date(settings.value.date):null)
const dateText=computed(()=>date.value?date.value.toLocaleDateString('es-ES',{day:'numeric',month:'long',year:'numeric',timeZone:'Europe/Madrid'}):'Un gran día está por llegar')
const countdown=computed(()=>{const t=Math.max(0,Math.floor(((date.value?.getTime()??now.value)-now.value)/1000));return [{value:Math.floor(t/86400),label:'días'},{value:Math.floor(t%86400/3600),label:'horas'},{value:Math.floor(t%3600/60),label:'minutos'},{value:t%60,label:'segundos'}]})
const practical=computed(()=>[{title:'Cómo llegar juntos',text:settings.value.transport,icon:Bus},{title:'Un lugar para descansar',text:settings.value.accommodation,icon:Hotel},{title:'Ven a celebrarlo',text:settings.value.dress_code,icon:Shirt}].filter(x=>x.text))
function login(){menuOpen.value=false;recovery.value=false;authOpen.value=true}
function changeRoute(){gameApp.value=location.hash==='#mascota';inviteToken.value=new URLSearchParams(location.hash.slice(1)).get('invite')||'';admin.value=location.pathname==='/admin'||location.hash==='#admin'}
function home(){gameApp.value=false;inviteToken.value='';history.pushState(null,'',appBase);admin.value=false;window.scrollTo(0,0)}
function openAdmin(){history.pushState(null,'',appBase+'#admin');admin.value=true;menuOpen.value=false;window.scrollTo(0,0)}
function recover(){recovery.value=true;authOpen.value=true}
async function load(){error.value='';try{const {data,error:e}=await db.from('wedding_settings').select('content').eq('id',1).single();fail(e);settings.value={...defaults,...data?.content};settingsLoaded.value=true}catch(e){error.value='No hemos podido actualizar los detalles. '+friendly(e)}}
function map(address:string){return 'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(address)}
function calendar(){if(!date.value)return;const format=(d:Date)=>d.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z/,'Z');const escape=(s:string)=>s.replaceAll('\\','\\\\').replaceAll('\n','\\n').replaceAll(',','\\,').replaceAll(';','\\;');const ics=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Laura Javier//Boda//ES','BEGIN:VEVENT','UID:laura-javier-wedding@huellas','DTSTAMP:'+format(new Date()),'DTSTART:'+format(date.value),'DTEND:'+format(new Date(date.value.getTime()+6*3600000)),'SUMMARY:'+escape('Boda de '+settings.value.couple),'LOCATION:'+escape(settings.value.ceremony_address||settings.value.location),'END:VEVENT','END:VCALENDAR'].join('\r\n');const u=URL.createObjectURL(new Blob([ics],{type:'text/calendar;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='boda-laura-javier.ics';a.click();URL.revokeObjectURL(u)}
onMounted(()=>{void load();void initializeAuth().catch(e=>{authReady.value=true;error.value=friendly(e)});clock=setInterval(()=>now.value=Date.now(),1000);window.addEventListener('popstate',changeRoute);window.addEventListener('hashchange',changeRoute);window.addEventListener('password-recovery',recover)})
onUnmounted(()=>{clearInterval(clock);window.removeEventListener('popstate',changeRoute);window.removeEventListener('hashchange',changeRoute);window.removeEventListener('password-recovery',recover)})
</script>
<template><AuthModal v-if="authOpen" :recovery="recovery" @close="authOpen=false"/><InvitePostcard v-if="inviteToken" :token="inviteToken" :settings="settings" @home="home" @login="login"/><AdminPanel v-else-if="admin" :key="`${isAdmin}-${settingsLoaded}`" :settings="settings" @home="home" @login="login" @updated="settings=$event"/><div v-else-if="gameApp" class="game-app"><DogGame :dog-name="settings.dog_name" :wedding-date="settings.date" :couple="settings.couple" @login="login" @close="home"/></div><template v-else><a class="skip-link" href="#contenido">Saltar al contenido</a><header class="site-header"><a href="#" class="brand" aria-label="Laura y Javier, inicio">L <i>&</i> J<span>NUESTRA BODA</span></a><nav :class="{open:menuOpen}" aria-label="Navegación principal"><a href="#historia" @click="menuOpen=false">Nuestra historia</a><a href="#dia" @click="menuOpen=false">El gran día</a><a href="#musica" @click="menuOpen=false">La música</a><a href="#aventura" @click="menuOpen=false">Una aventura <Paw/></a><a class="nav-invite" href="#mi-invitacion" @click="menuOpen=false">Mi invitación <ArrowUpRight :size="15"/></a></nav><button class="mobile-menu" @click="menuOpen=!menuOpen" :aria-expanded="menuOpen" aria-label="Abrir menú"><X v-if="menuOpen"/><Menu v-else/></button></header><main id="contenido"><div v-if="error" class="connection-error" role="alert">{{error}} <button @click="load" class="text-link">Reintentar</button></div><section class="hero"><div class="hero-photo"><img src="/images/couple.png" alt="Laura y Javier, juntos en la playa al atardecer" fetchpriority="high"/></div><div class="hero-copy"><span class="eyebrow"><span class="tiny-line"></span> NOS CASAMOS <span class="tiny-line"></span></span><h1>Laura <span>&</span><br/>Javier</h1><p class="hero-caption">Contigo, todos los caminos<br/>llevan a algo bonito.</p><div class="hero-date"><CalendarDays :size="17"/><span>{{dateText}}</span></div><p v-if="settings.location" class="hero-location">{{settings.location}}</p><a href="#mi-invitacion" class="btn">¿Nos acompañas? <Heart :size="16"/></a><a href="#historia" class="scroll-link">Nuestra historia empieza aquí <ArrowDown :size="16"/></a></div><div class="hero-footnote"><Paw/><span>Una historia de dos.<br/>Y unas cuantas huellas.</span></div><span class="hero-side-note">LO MEJOR ESTÁ POR VENIR</span></section><section class="welcome"><span class="eyebrow">FAMILIA, AMIGOS Y TODOS LOS NUESTROS</span><h2>Hay días que cambian una vida.<br/><em>Y personas que los hacen inolvidables.</em></h2><p>{{settings.welcome}}</p><div v-if="date&&date.getTime()>now" class="countdown"><div v-for="c in countdown" :key="c.label"><strong>{{String(c.value).padStart(2,'0')}}</strong><span>{{c.label}}</span></div></div><p v-else-if="date" class="eyebrow">EL DÍA QUE TANTO ESPERÁBAMOS</p><div v-else class="save-date"><CalendarDays :size="20"/> Pronto os contaremos cuándo y dónde</div><div class="paw-divider"><span></span><Paw/><span></span></div></section><section id="historia" class="section story-section"><div class="section-heading"><span class="eyebrow">PASO A PASO, HUELLA A HUELLA</span><h2>Nuestra historia</h2><p>No todos los caminos se planean.<br/>Algunos simplemente se encuentran.</p></div><div class="story-path"><article v-for="(s,i) in settings.story" :key="i" class="story-item" :class="{reverse:i%2!==0}"><div class="story-photo" :class="s.image"><img :src="appBase+'images/'+(['couple','home','dog'].includes(s.image)?s.image:'couple')+'.png'" :alt="s.image==='dog'?'Nuestro perrito marrón junto a la puerta':s.image==='home'?'Llaves de Laura y Javier y una casa de madera con la frase Lo soñamos, lo trabajamos, lo conseguimos':'Laura y Javier en la playa'" loading="lazy"/><span class="photo-caption">{{['nuestro lugar favorito: juntos','lo soñamos, lo conseguimos','amor del que deja huella'][i%3]}}</span></div><div class="path-marker"><Paw/><Paw/><Paw/></div><div class="story-copy"><span class="story-number">0{{i+1}}</span><h3>{{s.title}}</h3><p>{{s.text}}</p><Heart :size="17" class="little-heart"/></div></article></div></section><section class="quote-band"><Heart :size="22"/><p>La suerte de encontrarnos.<br/><em>Las ganas de elegirnos.</em></p><span>LAURA & JAVIER</span></section><section id="dia" class="section day-section"><div class="section-heading"><span class="eyebrow">EL SIGUIENTE PASO</span><h2>Un día para recordarlo todo</h2><p>Las sonrisas, los abrazos y ese último baile.</p></div><div class="locations"><article><span class="location-icon">♡</span><span class="eyebrow">EL SÍ, QUIERO</span><h3>{{settings.ceremony_name||'La ceremonia'}}</h3><p>{{settings.ceremony_time||'Horario por confirmar'}}</p><p>{{settings.ceremony_address||'Muy pronto compartiremos todos los detalles.'}}</p><a v-if="settings.ceremony_address" :href="map(settings.ceremony_address)" class="text-link" target="_blank" rel="noopener noreferrer"><MapPin :size="16"/> Cómo llegar <ArrowUpRight :size="14"/></a></article><article><span class="location-icon">♧</span><span class="eyebrow">BRINDAMOS POR LO QUE VIENE</span><h3>{{settings.reception_name||'La celebración'}}</h3><p>{{settings.reception_time||'Horario por confirmar'}}</p><p>{{settings.reception_address||'Un lugar para celebrar, reír y estar juntos.'}}</p><a v-if="settings.reception_address" :href="map(settings.reception_address)" class="text-link" target="_blank" rel="noopener noreferrer"><MapPin :size="16"/> Cómo llegar <ArrowUpRight :size="14"/></a></article></div><button v-if="date" class="btn secondary calendar-btn" @click="calendar"><CalendarDays :size="17"/> Guardar en mi calendario</button><div class="day-timeline"><div v-for="(s,i) in settings.schedule" :key="i"><Paw/><span>{{s.time||'Por confirmar'}}</span><h4>{{s.title}}</h4></div></div><div v-if="practical.length" class="practical-grid"><article v-for="p in practical" :key="p.title"><component :is="p.icon" :size="28"/><h3>{{p.title}}</h3><p class="preserve">{{p.text}}</p></article></div></section><SongForm :playlist="settings.spotify_playlist" @login="login"/><section id="aventura" class="section adventure-section" :class="{'pet-open':gameOpen}"><div class="adventure-copy"><span class="eyebrow">EL INVITADO CON MÁS PATITAS</span><h2>Un nuevo amigo.<br/><em>Mucho que cuidar.</em></h2><p>Nuestro compañero más fiel tiene su propio rincón. Dale de comer, prepara un baño de burbujas y sal a jugar con él.</p><p>Una mascota virtual para acompañarnos hasta la boda. Un poquito de cariño cada día, y muchas huellas por el camino.</p><div class="pixel-intro"><VirtualDog class="intro-dog"/><div><b>{{settings.dog_name}}</b><span>Experto en mimos y pequeñas aventuras</span></div></div><button v-if="!gameOpen" class="btn olive" @click="gameOpen=true"><Sparkles :size="17"/> Cuidar a nuestro perrito</button><p class="small muted">Comida, baños y siestas · Tu progreso se guarda</p></div><div class="adventure-visual" v-if="!gameOpen"><div class="dog-portrait"><img src="/images/dog.png" alt="Nuestro perrito marrón, el protagonista de la mascota virtual" loading="lazy"/></div><span class="portrait-label"><Paw/> El amor también tiene cuatro patas</span></div><DogGame v-else :dog-name="settings.dog_name" :wedding-date="settings.date" :couple="settings.couple" @login="login" @close="gameOpen=false"/></section><GuestArea @login="login"/><section class="closing"><Paw/><p>Nos vemos en el siguiente capítulo.</p><h2>Laura <i>&</i> Javier</h2><span>CON TODO NUESTRO CARIÑO</span><p v-if="settings.contact" class="preserve small">{{settings.contact}}</p></section></main><footer><p>Hecho de recuerdos, ilusión y alguna que otra huella.</p><button @click="openAdmin" class="text-link">El rincón de los novios <ArrowUpRight :size="14"/></button></footer></template></template>
